ALTER TABLE public.lines ADD COLUMN account_type text NOT NULL DEFAULT 'xtream' CHECK (account_type IN ('xtream','mac','both')), ADD COLUMN mac_address text UNIQUE, ADD COLUMN portal_disabled boolean NOT NULL DEFAULT false, ADD COLUMN portal_id bigint GENERATED BY DEFAULT AS IDENTITY, ADD COLUMN last_mac_login_at timestamptz, ADD COLUMN last_mac_login_ip text;
ALTER TABLE public.lines ADD CONSTRAINT lines_mac_format CHECK (mac_address IS NULL OR mac_address ~ '^00:1A:79:([0-9A-F]{2}:){2}[0-9A-F]{2}$'), ADD CONSTRAINT lines_mac_required CHECK (account_type = 'xtream' OR mac_address IS NOT NULL);
CREATE TABLE public.mac_portal_sessions (token_hash text PRIMARY KEY, line_id uuid NOT NULL REFERENCES public.lines(id) ON DELETE CASCADE, mac_address text NOT NULL, expires_at timestamptz NOT NULL DEFAULT now() + interval '24 hours');
GRANT ALL ON public.mac_portal_sessions TO service_role;
ALTER TABLE public.mac_portal_sessions ENABLE ROW LEVEL SECURITY;
CREATE INDEX mac_portal_sessions_line_idx ON public.mac_portal_sessions(line_id);
CREATE TABLE public.mac_portal_rate_limits (mac_address text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), requests integer NOT NULL DEFAULT 1);
GRANT ALL ON public.mac_portal_rate_limits TO service_role;
ALTER TABLE public.mac_portal_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.set_subscriber_mac(_line_id uuid, _account_type text, _mac text, _disabled boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _uid uuid := auth.uid(); _owner uuid;
BEGIN
 IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
 SELECT reseller_id INTO _owner FROM public.lines WHERE id = _line_id FOR UPDATE;
 IF _owner IS NULL OR NOT (public.has_role(_uid,'admin') OR (_owner = _uid AND public.has_role(_uid,'reseller'))) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 IF _account_type NOT IN ('xtream','mac','both') OR _account_type IS NULL THEN RAISE EXCEPTION 'Invalid account type'; END IF;
 UPDATE public.lines SET account_type = _account_type, mac_address = CASE WHEN _account_type = 'xtream' THEN NULL ELSE upper(trim(_mac)) END, portal_disabled = _disabled WHERE id = _line_id;
 DELETE FROM public.mac_portal_sessions WHERE line_id = _line_id;
END $$;
REVOKE ALL ON FUNCTION public.set_subscriber_mac(uuid,text,text,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_subscriber_mac(uuid,text,text,boolean) TO authenticated;
CREATE FUNCTION public.create_subscriber(_username text, _password text, _months integer, _account_type text DEFAULT 'xtream', _mac text DEFAULT NULL, _custom_host text DEFAULT '', _customer text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _line public.lines;
BEGIN
 IF _months = 0 THEN SELECT * INTO _line FROM public.create_test_line(_username,_password,_customer); ELSE SELECT * INTO _line FROM public.create_line(_username,_password,_months); END IF;
 PERFORM public.set_subscriber_mac(_line.id,_account_type,_mac,false);
 UPDATE public.lines SET custom_host = nullif(trim(_custom_host),'') WHERE id = _line.id;
 RETURN _line.id;
END $$;
REVOKE ALL ON FUNCTION public.create_subscriber(text,text,integer,text,text,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_subscriber(text,text,integer,text,text,text,text) TO authenticated;
CREATE FUNCTION public.update_subscriber(_line_id uuid, _password text, _custom_host text, _max_connections integer, _account_type text, _mac text, _disabled boolean DEFAULT false, _expires_at timestamptz DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _charge integer;
BEGIN
 _charge := public.update_line(_line_id,_password,_custom_host,_max_connections,_expires_at);
 PERFORM public.set_subscriber_mac(_line_id,_account_type,_mac,_disabled);
 RETURN _charge;
END $$;
REVOKE ALL ON FUNCTION public.update_subscriber(uuid,text,text,integer,text,text,boolean,timestamptz) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.update_subscriber(uuid,text,text,integer,text,text,boolean,timestamptz) TO authenticated;
CREATE FUNCTION public.authorize_mac_portal(_mac text, _token_hash text DEFAULT NULL, _new_token_hash text DEFAULT NULL, _ip text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _line public.lines; _requests integer;
BEGIN
 IF _mac IS NULL OR _mac !~ '^00:1A:79:([0-9A-F]{2}:){2}[0-9A-F]{2}$' THEN RETURN jsonb_build_object('error','Invalid MAC address'); END IF;
 SELECT * INTO _line FROM public.lines WHERE mac_address = _mac AND account_type IN ('mac','both');
 IF _line.id IS NULL THEN RETURN jsonb_build_object('error','Unknown MAC address'); END IF;
 IF _line.portal_disabled THEN RETURN jsonb_build_object('error','Account disabled'); END IF;
 IF _line.expires_at <= now() THEN RETURN jsonb_build_object('error','Subscription expired'); END IF;
 INSERT INTO public.mac_portal_rate_limits(mac_address) VALUES (_mac) ON CONFLICT(mac_address) DO UPDATE SET requests = CASE WHEN mac_portal_rate_limits.window_start <= now() - interval '1 minute' THEN 1 ELSE mac_portal_rate_limits.requests + 1 END, window_start = CASE WHEN mac_portal_rate_limits.window_start <= now() - interval '1 minute' THEN now() ELSE mac_portal_rate_limits.window_start END RETURNING requests INTO _requests;
 IF _requests > 120 THEN RETURN jsonb_build_object('error','Too many requests; retry shortly'); END IF;
 IF _new_token_hash IS NOT NULL THEN
  IF _new_token_hash !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('error','Invalid session'); END IF;
  DELETE FROM public.mac_portal_sessions WHERE expires_at <= now() AND line_id = _line.id;
  INSERT INTO public.mac_portal_sessions(token_hash,line_id,mac_address) VALUES (_new_token_hash,_line.id,_mac);
  UPDATE public.lines SET last_mac_login_at = now(), last_mac_login_ip = left(_ip,100) WHERE id = _line.id;
 ELSIF NOT EXISTS (SELECT 1 FROM public.mac_portal_sessions WHERE token_hash = _token_hash AND line_id = _line.id AND mac_address = _mac AND expires_at > now()) THEN
  RETURN jsonb_build_object('error','Invalid or expired token');
 END IF;
 RETURN jsonb_build_object('lineId',_line.id,'id',_line.portal_id,'username',_line.username,'password',_line.password,'mac',_mac,'expiresAt',_line.expires_at,'maxConnections',_line.max_connections);
END $$;
REVOKE ALL ON FUNCTION public.authorize_mac_portal(text,text,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.authorize_mac_portal(text,text,text,text) TO service_role;